-- 038 — Add 50 language questions
--
-- Pure insert, no passage. Ids are deterministic:
-- One stem, 'Which word is misspelled?', is already used by migration 024,
-- so it is asked here as 'Which word below is misspelled?' — same question,
-- different id, so the new row is not swallowed by ON CONFLICT.
-- md5(section || '|' || prompt)::UUID with ON CONFLICT DO NOTHING, so
-- re-running this file is a no-op. Nothing existing is deleted or updated,
-- and user_question_history is never touched.

WITH q(prompt, options, correct_index, difficulty, explanation) AS (VALUES
  ('Which sentence contains a mistake in capitalization?', '["We celebrate thanksgiving at my grandmother''s house.", "Our new neighbors moved here from Brazil last summer.", "The Mississippi River flows past St. Louis.", "No mistakes"]'::JSONB, 0, 1, 'Holiday names are proper nouns, so Thanksgiving needs a capital T. The other sentences are already right: Brazil is the name of a country, and the Mississippi River and St. Louis are named places. Common nouns such as grandmother stay lowercase unless they open the sentence.'),
  ('Which sentence contains an error in verb agreement?', '["The players on the team practice every afternoon.", "My sister and her friend was late to the concert.", "There are four apples in the bowl.", "No mistakes"]'::JSONB, 1, 1, 'Two subjects joined by and make a compound subject, which is plural, so the verb must be were late. The other sentences are fine: players takes the plural verb practice, and in a sentence beginning with there, the verb matches what follows it, so four apples takes are.'),
  ('Which sentence contains a punctuation error?', '["Yes, I would like another slice.", "We need milk, bread, and eggs.", "Where are you going", "No mistakes"]'::JSONB, 2, 1, 'A direct question needs a question mark, so the sentence asking where are you going should not stop with nothing at all. The others are punctuated correctly: a comma follows the introductory yes, and commas separate the items milk, bread, and eggs in the list.'),
  ('Which sentence includes an error?', '["My friends and I rode our bikes to the park.", "The teacher handed out the tests quickly.", "She sings beautiful when she is nervous.", "No mistakes"]'::JSONB, 2, 1, 'Adverbs describe verbs and adjectives describe nouns. Sings is a verb, so the sentence needs beautifully, not beautiful. The others are correct: friends and I is the right subject pair, and quickly is already an adverb describing how the teacher handed out the tests.'),
  ('Which sentence contains a usage error?', '["Your going to love this movie.", "You''re the fastest runner in our class.", "Your backpack is under the bench.", "No mistakes"]'::JSONB, 0, 1, 'Your shows possession, while you''re is the contraction of you are. The sentence means you are going to love this movie, so it needs you''re. The other sentences use both forms correctly: you''re the fastest runner means you are, and your backpack shows that the backpack belongs to you.'),
  ('Which sentence contains an error in word choice?', '["The loud music affected my concentration.", "The new rule had a strong effect on attendance.", "Their new puppy chews everything.", "No mistakes"]'::JSONB, 3, 1, 'Nothing needs fixing here. Affect is the verb, so the loud music affected your concentration, and effect is the noun, so the rule had an effect on attendance. Their is the correct possessive before puppy. When all three sentences hold up, the answer is that there are no mistakes.'),
  ('Which sentence contains a capitalization error?', '["In September we will study the Civil War.", "My aunt speaks French and Portuguese.", "We drove east on Highway 50 toward the mountains.", "No mistakes"]'::JSONB, 3, 1, 'All three are already correct. Months such as September and named historical events like the Civil War are capitalized, and languages built from proper nouns, such as French and Portuguese, are too. East stays lowercase because it names a direction here rather than a region, so nothing needs changing.'),
  ('Which sentence should be corrected?', '["He don''t want to go to the assembly.", "She doesn''t like watching scary movies at night.", "They don''t have practice today.", "No mistakes"]'::JSONB, 0, 1, 'Subjects and verbs have to agree. He, she, and it take doesn''t, while I, you, we, and they take don''t, so the sentence should read he doesn''t want to go to the assembly. The other two follow that rule correctly: she pairs with doesn''t about watching scary movies, and they pairs with don''t about practice.'),
  ('Which sentence contains an error in pronoun use?', '["Marcus and I finished the project.", "The prize was shared by Ana and me.", "Him and Tyler built the model.", "No mistakes"]'::JSONB, 2, 1, 'People doing the action need subject pronouns, so it should read he and Tyler built the model. Test it by dropping the other name: him built the model is clearly wrong. The others are right because Marcus and I is the subject that finished the project, and me follows the preposition by in the sentence about the prize.'),
  ('Which sentence contains an apostrophe error?', '["The boy''s jacket is on the hook.", "The teachers lounge is down the hall.", "Carla''s brother plays the trumpet.", "No mistakes"]'::JSONB, 1, 1, 'The lounge belongs to more than one teacher, so it needs a plural possessive: teachers'' lounge, with the apostrophe after the s. The others are correct singular possessives, since the boy''s jacket belongs to one boy and Carla''s brother shows one Carla. Ask how many owners there are first.'),
  ('Which sentence is not written correctly?', '["We seen the fireworks from the roof.", "We watched the fireworks from the roof.", "We have seen that movie twice.", "No mistakes"]'::JSONB, 0, 1, 'Seen is a past participle and cannot stand on its own; it needs a helping verb. The simple past of see is saw, so it should read we saw the fireworks from the roof. The other sentences show both correct patterns: watched is a plain past tense, and have seen supplies the helper.'),
  ('Which sentence contains a mistake in grammar or punctuation?', '["Before the game started, we ate dinner.", "My shoes, which I bought last month, are already worn out.", "The dog barked at the mail carrier.", "No mistakes"]'::JSONB, 3, 1, 'All three are correct, so nothing needs fixing. An introductory clause such as before the game started takes a comma after it. The commas around which I bought last month are a matched pair setting off extra information. The sentence about the dog and the mail carrier is a plain statement.'),
  ('Which sentence contains an error in the use of commas?', '["After the movie, we walked home.", "I bought apples, oranges and bananas.", "My best friend Jenna, plays the violin.", "No mistakes"]'::JSONB, 2, 1, 'Never split a subject from its verb with a single comma; my best friend Jenna plays the violin needs no comma at all. The others are fine. The comma after the movie follows an introductory phrase, and the serial comma is optional, so apples, oranges and bananas is acceptable.'),
  ('Which one of these sentences contains an error?', '["The list of names were posted outside the office.", "Several students were waiting outside the office.", "The box of markers is on my desk.", "No mistakes"]'::JSONB, 0, 1, 'Find the real subject: it is list, which is singular, so the verb must be was posted. The words of names sit in a prepositional phrase, and a phrase between the subject and its verb never changes the verb''s number. Several students and the box of markers follow the same rule correctly.'),
  ('Which sentence contains an error in end punctuation?', '["What a great catch that was!", "Please close the door on your way out.", "Did you remember to feed the cat.", "No mistakes"]'::JSONB, 2, 1, 'A sentence that asks something directly ends with a question mark, so did you remember to feed the cat needs one instead of a period. The others are right: an exclamation about a great catch takes an exclamation point, and a polite command such as please close the door ends with a period.'),
  ('Which sentence contains an error in standard usage?', '["I could have finished sooner.", "I should of studied harder.", "We would have called you.", "No mistakes"]'::JSONB, 1, 1, 'Should of is not a real phrase; it comes from mishearing the contraction should''ve, which is short for should have. Write should have studied harder. The other sentences already use the full form, with could have finished and would have called, and those are the patterns to copy.'),
  ('Which sentence contains an error in agreement?', '["Neither of my brothers likes broccoli.", "The team lost its opening game.", "Each of the answers was correct.", "No mistakes"]'::JSONB, 3, 1, 'All three are correct. Neither and each are singular pronouns, so they take likes and was even though brothers and answers are plural. Team is a collective noun treated as one unit, so it takes the singular pronoun its. Since nothing needs changing, no mistakes is the answer.'),
  ('Which sentence contains an error in quotation punctuation?', JSONB_BUILD_ARRAY('Mrs. Ortiz asked, are we ready to begin?', 'Mrs. Ortiz asked, "Are we ready to begin?"', 'Mrs. Ortiz asked whether we were ready to begin.', 'No mistakes'), 0, 1, 'A direct quotation must sit inside quotation marks and start with a capital letter, so the words are we ready to begin need both. The version that already has quotation marks is correct, and the version that reports the question indirectly, using whether, needs no quotation marks at all.'),
  ('Which sentence contains an error in a plural form?', '["The children played in the yard behind the school.", "We saw three deers at the edge of the field.", "She packed two loaves of bread.", "No mistakes"]'::JSONB, 1, 1, 'Deer keeps the same form in the singular and the plural, so it should read we saw three deer. A few animal words work this way, including sheep and fish. The other sentences use correct irregular plurals: children is the plural of child, and loaves is the plural of loaf.'),
  ('Which sentence has a mistake in it?', '["Our school is much bigger than the one across town.", "This is the best pizza in town.", "Of the two puppies, the beagle is the smallest.", "No mistakes"]'::JSONB, 2, 1, 'Use the comparative form when you compare exactly two things, so of the two puppies, the beagle is the smaller. Save the superlative for three or more. The others are right, since bigger compares our school with one other school, and best pizza in town compares one pizza against many.'),
  ('Which of these is a sentence fragment rather than a complete sentence?', '["Running through the sprinkler on a hot afternoon.", "The kids ran through the sprinkler.", "It was a hot afternoon.", "Everyone laughed and cheered from the back porch steps."]'::JSONB, 0, 1, 'A complete sentence needs a subject and a main verb. Running through the sprinkler on a hot afternoon has neither, because running here is a participle describing an action rather than the verb of the sentence. Each other choice has someone doing something, such as the kids ran or everyone laughed.'),
  ('Which sentence is a run-on sentence?', '["The rain stopped, and the sun came out.", "The rain stopped the sun came out.", "When the rain stopped, the sun came out.", "After the rain, the sun came out."]'::JSONB, 1, 1, 'A run-on jams two complete sentences together with nothing between them, and the rain stopped and the sun came out are each independent clauses. Fix it with a comma plus and, or with a semicolon. Starting with when turns the first clause into a dependent one, which is also correct.'),
  ('Which sentence contains an error in punctuation?', '["The concert, which had been postponed twice, finally took place in June.", "We were told to bring the following: a tent, a sleeping bag, and a flashlight.", "My cousin lives in Portland Oregon and works as a nurse.", "No mistakes"]'::JSONB, 2, 2, 'A city and its state are separated by a comma: Portland, Oregon. The others are correct. The clause about the concert being postponed twice is nonessential, so a pair of commas sets it off, and the colon is legal because the words before it form a complete clause on their own.'),
  ('Which sentence contains an error in wording?', '["The reason for the delay is because the truck broke down.", "The reason for the delay is that the truck broke down.", "The shipment was delayed because the truck broke down.", "No mistakes"]'::JSONB, 0, 3, 'Reason already announces a cause, so following it with because states the same idea twice. Standard English uses the reason for the delay is that the truck broke down. The other sentences avoid the doubling, one by using that and one by starting with the shipment was delayed.'),
  ('Which sentence contains an error in verb tense?', '["When the bell rings, the students rush out, and the hallway fills with noise.", "As soon as the bell rang, the students rushed out, and the hallway fills with noise.", "As soon as the bell rang, the students rushed out, and the hallway filled with noise.", "No mistakes"]'::JSONB, 1, 3, 'Keep the tense consistent inside one sentence. This version starts in the past with rang and rushed, then jumps to the present with fills for no reason; it should end with filled. The all-present version, where the bell rings and the hallway fills, is consistent, and so is the all-past version.'),
  ('Which sentence contains an error in subject-verb agreement?', '["Neither the students nor the teacher was aware of the change.", "Either the twins or their mother drives them to practice.", "Not only the coach but also the players was disappointed.", "No mistakes"]'::JSONB, 2, 3, 'With paired conjunctions such as either or and not only but also, the verb agrees with whichever subject is closer to it. Here that subject is the plural players, so it must be were disappointed. The same rule makes was correct after teacher and drives correct after their mother.'),
  ('Which sentence contains an error in punctuation or usage?', '["The committee announced its decision on Friday.", "She wanted to quickly finish the assignment before dinner.", "We invited three people: my aunt, my cousin, and my neighbor.", "No mistakes"]'::JSONB, 3, 3, 'All three hold up. A collective noun like committee acts as one unit, so its is the right pronoun. A split infinitive such as to quickly finish is not an error in modern usage, even though it looks suspicious. The colon is fine because a complete clause comes before it.'),
  ('Which sentence contains an error in the placement of a modifier?', '["The teacher explained the rule to the students that had been changed.", "The teacher explained to the students the rule that had been changed.", "The rule that had been changed was explained to the students by the teacher.", "No mistakes"]'::JSONB, 0, 3, 'A modifying clause has to sit next to the word it describes. As written, that had been changed lands right after the students, so it seems to describe the students instead of the rule. Moving the rule beside its clause fixes the problem, which is what the other versions already do.'),
  ('Which sentence contains an error in the punctuation of a quotation?', JSONB_BUILD_ARRAY('The principal called it "a remarkable achievement."', 'Did the coach really say, "Practice is canceled?"', 'She asked, "When does the bus leave?"', 'No mistakes'), 1, 3, 'The quoted words are a statement and the whole sentence is the question, so the question mark belongs outside the closing quotation mark, not inside it. Where the quoted words ask when does the bus leave, the question belongs to the quotation, so the mark stays inside. The quoted phrase about a remarkable achievement needs no question mark at all.'),
  ('Which sentence contains an error in parallel structure?', '["The job requires patience, creativity, and attention to detail.", "She is responsible for scheduling meetings, ordering supplies, and training new staff.", "The manual explains how to assemble the shelf, how to mount it, and the way you anchor it.", "No mistakes"]'::JSONB, 2, 3, 'Items in a series must share the same grammatical form. Two how to phrases followed by the way you anchor it breaks the pattern, so it should read how to anchor it. The other sentences stay parallel: patience, creativity, and attention are three nouns, and scheduling, ordering, and training are three matching -ing forms.'),
  ('Which sentence contains an error a careful editor would flag?', '["Fewer than twenty students signed up, so the trip was canceled.", "The amount of rain that fell exceeded last year''s total.", "Between the two proposals, hers is the more practical.", "No mistakes"]'::JSONB, 3, 3, 'All three are correct. Use fewer for things you can count, such as students, and amount for things measured in bulk, such as rain. When comparing exactly two proposals, the comparative more practical is right rather than most practical. Nothing here needs fixing, so no mistakes is the answer.'),
  ('Which sentence contains an error in comparison?', '["The new stadium holds more fans than any stadium in the league.", "The new stadium holds more fans than any other stadium in the league.", "The new stadium is the largest in the league.", "No mistakes"]'::JSONB, 0, 3, 'In a comparison, a thing cannot belong to the group it is being compared against. The new stadium is in the league, so as written it would have to hold more fans than itself. Adding other excludes it. Calling it the largest in the league is a superlative, which is fine.'),
  ('Which sentence contains an error in the use of a semicolon or colon?', '["The results were clear; the experiment had failed.", "There is only one thing left to do; finish the report.", "Our itinerary includes three cities: Denver, Santa Fe, and Tucson.", "No mistakes"]'::JSONB, 1, 3, 'A semicolon joins two complete sentences, but finish the report cannot stand alone as one, so a colon is needed to introduce it. The other examples are right: a semicolon links the two full clauses about the results, and a colon introduces the list of Denver, Santa Fe, and Tucson.'),
  ('Which word below is misspelled?', '["surprise", "goverment", "attention", "No mistakes"]'::JSONB, 1, 1, 'Government is built from govern plus the ending -ment, so the n in govern stays in place. Say the base word in your head before you write it. Surprise and attention are spelled correctly here, though surprise deserves a second look because the first r is easy to drop.'),
  ('Choose the misspelled word.', '["arguement", "grammar", "familiar", "No mistakes"]'::JSONB, 0, 1, 'Argument drops the silent e from argue before the ending -ment. Compare truly, which drops the e from true. Grammar and familiar are spelled correctly, though grammar tempts people to finish it with -er, since so many other words do. Trust the rule rather than the sound.'),
  ('Which of these words is spelled incorrectly?', '["knowledge", "restaurant", "athelete", "No mistakes"]'::JSONB, 2, 1, 'Athlete has only two syllables: ath-lete. There is no e between the h and the l, even though many people say ath-a-lete out loud. Knowledge and restaurant are spelled correctly, and restaurant is the harder one to trust because of the silent letters in the middle.'),
  ('Which word contains a spelling error?', '["until", "across", "beginning", "No mistakes"]'::JSONB, 3, 1, 'All three are spelled correctly, so nothing here is wrong. Until ends with one l, unlike the separate word till. Across has one c, not two. Beginning doubles the n because the stress falls on the last syllable of begin before -ing is added, which is a rule worth remembering.'),
  ('One of these words is spelled incorrectly. Which one?', '["forty", "eighth", "ninty", "No mistakes"]'::JSONB, 2, 1, 'Ninety keeps the e from nine, so think of nine plus -ty. Forty is the word that breaks the pattern, dropping the u from four, and it is spelled correctly here. Eighth is correct too: it is eight with a single h added, not an extra t.'),
  ('Which word is misspelled in this group?', '["reccommend", "committee", "definitely", "No mistakes"]'::JSONB, 0, 3, 'Recommend has one c and two m''s, because it is re plus commend. If you can spell commend, the rest follows. Committee and definitely are both correct here, and definitely is the one to watch, since it hides the smaller word finite inside the middle of it.'),
  ('Select the misspelled word.', '["parallel", "sincerely", "vacuum", "No mistakes"]'::JSONB, 3, 3, 'All three are spelled correctly. Parallel has a double l in the middle only, with a single l at the end, and the shape of the word can help you remember. Sincerely keeps the e from sincere before -ly, and vacuum really does have two u''s in a row.'),
  ('Which of the following words is spelled incorrectly?', '["exaggerate", "posession", "rhyme", "No mistakes"]'::JSONB, 1, 3, 'Possession has two pairs of s''s: pos-sess-ion. A hook that helps is that possession possesses more s''s than almost any word its size. Exaggerate and rhyme are correct here, and rhyme is worth noticing because its y is doing the work of a vowel.'),
  ('Which sentence best combines these two sentences? ''The storm knocked down a tree.'' and ''The tree blocked our driveway.''', '["The storm knocked down a tree, it blocked our driveway.", "The storm knocked down a tree that blocked our driveway.", "The storm knocked down a tree, and blocking our driveway.", "The storm knocked down a tree, but it blocked our driveway."]'::JSONB, 1, 1, 'A relative clause folds the second fact into the first without repeating the tree: the storm knocked down a tree that blocked our driveway. Joining the two with only a comma creates a comma splice, the version using blocking has no working verb, and but wrongly signals a contrast.'),
  ('Which sentence is the clearest and most concise?', '["Due to the fact that she was tired, she went to bed early.", "On account of being tired, an early bedtime was chosen by her.", "Because she was tired, she went to bed early.", "She went to bed early, the reason being that she was tired."]'::JSONB, 2, 1, 'The clearest version keeps a subject doing an action and cuts the filler: because she was tired, she went to bed early. Due to the fact that and on account of are long ways of saying because, and the reason being that adds words while pushing the real action into a weak phrase.'),
  ('Which sentence best introduces a paragraph about the benefits of reading for pleasure?', '["Students who read for pleasure build stronger vocabularies and focus.", "Last summer I checked out three books from the public library downtown.", "Libraries are usually open on weekends and most weekday evenings.", "Reading is a thing that many different kinds of people enjoy doing."]'::JSONB, 0, 1, 'A topic sentence names the subject and makes a claim the paragraph can then support, which is what the sentence about vocabularies and focus does. Checking out three books last summer is a personal detail, library hours are off topic, and saying reading is a thing people enjoy makes no claim to develop.'),
  ('Which transition best completes the sentence? ''The bridge was closed for repairs; ______, drivers had to take the long way around town.''', '["however", "for instance", "nevertheless", "as a result"]'::JSONB, 3, 2, 'The detour is the consequence of the closure, so the sentence needs a cause-and-effect transition. However and nevertheless both signal a contrast, which would mean the closure somehow did not affect drivers, and for instance introduces an example rather than a result.'),
  ('Which sentence does NOT belong in this paragraph? (1) Sea otters spend nearly their whole lives in the water. (2) Their thick fur traps air and keeps them warm in cold currents. (3) Kelp is harvested commercially for use in ice cream and toothpaste. (4) Otters often wrap themselves in kelp so they do not drift away while sleeping.', '["Sea otters spend nearly their whole lives in the water.", "Their thick fur traps air and keeps them warm in cold currents.", "Kelp is harvested commercially for use in ice cream and toothpaste.", "Otters often wrap themselves in kelp so they do not drift away while sleeping."]'::JSONB, 2, 2, 'Every other sentence tells you something about how sea otters survive in the water. The fact about kelp being harvested for ice cream and toothpaste shifts to a different subject and breaks the paragraph''s unity. It feels connected because kelp appears again later, but a repeated word is not a shared topic.'),
  ('Sentences 1-4 appear in scrambled order. Which arrangement makes the most logical paragraph? 1. The dough must then rest for an hour so the gluten relaxes. 2. Begin by stirring the flour, water, and yeast together in a large bowl. 3. Once it has doubled in size, punch it down and shape it into a loaf. 4. Knead the mixture until it is smooth and springs back when pressed.', '["2 - 1 - 4 - 3", "2 - 4 - 1 - 3", "4 - 2 - 1 - 3", "2 - 4 - 3 - 1"]'::JSONB, 1, 3, 'Read the signal words. Sentence 2 says begin, so it starts. You knead the mixture in sentence 4 before the dough can rest in sentence 1, since it is not dough until it is kneaded. And once it has doubled in size, in sentence 3, can only follow the resting hour.'),
  ('Where does this sentence best fit? ''Even so, the cost of the equipment kept many schools from joining.'' Paragraph: (1) The new robotics league promised to reach students in every district. (2) Organizers waived entry fees and provided free coaching. (3) By spring, only a dozen teams had registered. (4) Next year the league plans to lend kits to any school that asks.', '["Between sentences 2 and 3", "Before sentence 1", "Between sentences 1 and 2", "After sentence 4"]'::JSONB, 0, 3, 'Even so signals a contrast with something already stated, and here that is the waived fees and free coaching in sentence 2. It also explains the low turnout reported in sentence 3, so it has to sit between those two. A transition needs the idea it contrasts with to come first.'),
  ('Which revision best improves this sentence? ''The report, which was written by the committee, contained recommendations that were made about how the budget should be handled in the future.''', '["The report written by the committee contained recommendations about how the budget should be handled in the future by the district.", "Recommendations about the future handling of the budget were contained in the report that had been written by the committee.", "The committee''s report recommended how to handle the budget in the future.", "The report by the committee had in it recommendations concerning future budget handling."]'::JSONB, 2, 3, 'The strongest revision makes the real actor the subject and the real action the verb: the committee''s report recommended how to handle the budget. The other versions keep weak verbs such as contained and had in it, or push the recommendations into a passive phrase, so they run longer without saying more.'),
  ('A paragraph argues that cities should build more protected bike lanes. Which sentence best supports that argument with evidence?', '["Many people in the suburbs say they enjoy riding their bicycles on quiet weekend mornings.", "Bike lanes are painted bright green in some downtown neighborhoods.", "Cars and bicycles do not always get along well on crowded city streets.", "Protected bike lanes cut cyclist crashes by nearly forty percent."]'::JSONB, 3, 3, 'Evidence is a specific, checkable fact that backs the claim, and cutting cyclist crashes by nearly forty percent does that. Saying suburban riders enjoy quiet mornings is a personal preference, noting that lanes are painted bright green is a descriptive detail, and saying cars and bicycles do not always get along is too vague.')
)
INSERT INTO questions (id, section, passage, prompt, options, correct_index, difficulty, explanation)
SELECT md5('language' || '|' || q.prompt)::UUID, 'language'::section_type, NULL,
       q.prompt, q.options, q.correct_index, q.difficulty, q.explanation
FROM q
ON CONFLICT (id) DO NOTHING;

-- ── Verification: expect 50 rows ─────────────────────────────────────
SELECT '038 language' AS migration, COUNT(*)::TEXT AS present, '50' AS expected
FROM questions
WHERE id IN (
  md5('language' || '|' || 'Which sentence contains a mistake in capitalization?')::UUID,
  md5('language' || '|' || 'Which sentence contains an error in verb agreement?')::UUID,
  md5('language' || '|' || 'Which sentence contains a punctuation error?')::UUID,
  md5('language' || '|' || 'Which sentence includes an error?')::UUID,
  md5('language' || '|' || 'Which sentence contains a usage error?')::UUID,
  md5('language' || '|' || 'Which sentence contains an error in word choice?')::UUID,
  md5('language' || '|' || 'Which sentence contains a capitalization error?')::UUID,
